files.solution.py:
def pack(s):
    out = ''
    i = 0
    for j in range(len(s) + 1):
        if j == len(s) or s[j] != s[i]:
            length = j - i
            if length > 3:
                out += s[i] + str(length)
            else:
                out += s[i:j]
            i = j
    return out

