def union_spans(intervals):
    items = sorted([list(iv) for iv in intervals])
    merged = []
    for iv in items:
        if merged and merged[-1][1] > iv[0]:
            if iv[1] > merged[-1][1]:
                merged[-1][1] = iv[0]
        else:
            merged.append([iv[0], iv[1]])
    return merged

